import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Types of finance projects","description":"","frontmatter":{"title":"Types of finance projects"},"headers":[],"relativePath":"docs/personal-finance/types-of-finance-projects.md","filePath":"docs/personal-finance/types-of-finance-projects.md","lastUpdated":1794529254000}'),r={name:"docs/personal-finance/types-of-finance-projects.md"};function s(i,e,c,d,p,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="types-of-finance-projects" tabindex="-1">Types of finance projects <a class="header-anchor" href="#types-of-finance-projects" aria-label="Permalink to &quot;Types of finance projects&quot;">​</a></h1><p>Choose a project for the records you want to understand. You can have more than one project of each kind.</p><ul><li><strong>Banking + Credit Cards</strong> — checking, savings and credit-card activity; spending, income and recurring charges.</li><li><strong>Investment</strong> — brokerage and retirement-account statements; holdings, allocation and performance.</li><li><strong>Assets / Liabilities</strong> — property, private investments and debts, with records you enter or link to transactions.</li><li><strong>Retail Purchases</strong> — item-level order histories, currently Amazon, including orders, returns and refunds.</li><li><strong>General Documents</strong> — personal documents to search and discuss with AI. Trust documents and tax returns can be added here too.</li></ul><h2 id="a-typical-setup" tabindex="-1">A typical setup <a class="header-anchor" href="#a-typical-setup" aria-label="Permalink to &quot;A typical setup&quot;">​</a></h2><p>Start with bank and card statements in one project and brokerage statements in another. Add other kinds of records when useful. You can create a project first and import files later.</p><p>Use a <strong>Standard Workbook</strong> to combine finance projects for a <a href="/docs/personal-finance/combined-finance">household-wide view</a>, or a <strong>Retirement Planning</strong> workbook for a <a href="/docs/personal-finance/retirement">retirement outlook</a>. Workbooks draw on projects rather than importing statements themselves.</p>',6)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
